### Bare-Metal Clock Configuration for STM32G474 (168 MHz from 8 MHz HSE)

Here is the complete bare-metal CMSIS C code configuring the STM32G474 clock tree to achieve $\text{SYSCLK} = \text{HCLK} = \text{PCLK1} = \text{PCLK2} = 168\text{ MHz}$ using an external 8 MHz crystal (HSE).

```c
#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable power interface clock (PWR) to access PWR registers */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Configure Power Range 1 Boost Mode:
     * For SYSCLK > 150 MHz (up to 170 MHz), clear the R1MODE bit in PWR_CR5
     * (STM32G474 Reference Manual RM0440, Table 38, Section 6.1.5).
     */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Configure Flash read latency:
     * In Range 1 Boost Mode at 168 MHz, flash access requires 4 wait states (WS)
     * (RM0440, Table 9: 4 WS for 136 < HCLK <= 170 MHz).
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Wait until the flash latency setting takes effect */
    }

    /* 4. Enable HSE oscillator and wait for it to stabilize */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Busy-wait until HSE is ready */
    }

    /* 5. Configure Main PLL:
     * - Source: HSE (8 MHz) -> PLLSRC = 11b
     * - Input prescaler: PLLM = 1 (bits 7:4 = 0000b) -> f_PLL_IN = 8 MHz / 1 = 8 MHz (spec: 2.66 - 16 MHz)
     * - Multiplier: PLLN = 42 (bits 14:8 = 42) -> f_VCO = 8 MHz * 42 = 336 MHz (spec: 96 - 344 MHz)
     * - Divider: PLLR = 2 (bits 26:25 = 00b) -> f_PLL_R = 336 MHz / 2 = 168 MHz
     * - Enable PLL 'R' output: PLLREN (bit 24)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (0 << RCC_PLLCFGR_PLLM_Pos) |
                   (42 << RCC_PLLCFGR_PLLN_Pos) |
                   (0 << RCC_PLLCFGR_PLLR_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* 6. Enable the PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Busy-wait until PLL is locked */
    }

    /* 7. Safe Clock Transition for HCLK > 80 MHz / SYSCLK > 150 MHz:
     * RM0440 Section 6.1.5 & Section 7.2.7 require prescaling HCLK by 2 during the switch.
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;

    /* 8. Switch SYSCLK source to PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Busy-wait until PLL is selected as system clock source */
    }

    /* 9. Wait for at least 1 us in intermediate state before full speed */
    for (volatile int i = 0; i < 200; ++i) {
        __NOP();
    }

    /* 10. Set AHB prescaler to 1 (HCLK = SYSCLK = 168 MHz)
     * APB1 (PPRE1) and APB2 (PPRE2) remain at reset default DIV1 (/1),
     * yielding PCLK1 = PCLK2 = 168 MHz.
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;

    /* Configuration complete: SYSCLK = HCLK = PCLK1 = PCLK2 = 168 MHz */
    while (1) {
    }
}
